command:
socket = socketlib.registerModule(FqCardEngineModule.moduleName);
await socket.executeAsGM('updateDeckForUser', game.userId);

let deck = game.cards.find(c => c.system.fq.type === 'DECK' && c.ownership[game.userId] === 3)
let spellBook = game.cards.find(c => c.system.fq.type === 'SPELLBOOK' && c.ownership[game.userId] === 3)

if (deck) {
  deck.sheet.render(true, { position: {
        left: 110,
        top: 100
  }});
}

if (spellBook) {
    spellBook.sheet.render(true, { position: {
        left: 110 + deck.sheet.position.width,
        top: 100
    }});
}
